// Minimal command-line argument parser mirroring Python's argparse behavior
// for the options used by test2.mjs.

export class ArgumentError extends Error {}

const USAGE = 'usage: test2.mjs [-h] --key KEY --val VAL';

function exitWithError(message) {
  console.error(USAGE);
  console.error(`test2.mjs: error: ${message}`);
  process.exit(2);
}

function printHelp() {
  console.log(USAGE);
  console.log('');
  console.log('options:');
  console.log('  -h, --help  show this help message and exit');
  console.log('  --key KEY');
  console.log('  --val VAL');
  process.exit(0);
}

/**
 * Parse argv for the string options `--key` and `--val` (both required).
 * Supports `--opt value` and `--opt=value` forms, like argparse.
 *
 * @param {string[]} argv - process.argv slice (typically process.argv.slice(2))
 * @returns {{ key: string, val: string }}
 */
export function parseArgs(argv) {
  const values = { key: undefined, val: undefined };
  const optionNames = ['--key', '--val'];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      printHelp();
    }

    let name = token;
    let inlineValue;
    const eq = token.indexOf('=');
    if (token.startsWith('--') && eq !== -1) {
      name = token.slice(0, eq);
      inlineValue = token.slice(eq + 1);
    }

    if (!optionNames.includes(name)) {
      exitWithError(`unrecognized arguments: ${token}`);
    }

    const field = name.slice(2);
    if (inlineValue !== undefined) {
      values[field] = inlineValue;
    } else {
      if (i + 1 >= argv.length) {
        exitWithError(`argument ${name}: expected one argument`);
      }
      values[field] = argv[++i];
    }
  }

  const missing = optionNames.filter((n) => values[n.slice(2)] === undefined);
  if (missing.length > 0) {
    exitWithError(`the following arguments are required: ${missing.join(', ')}`);
  }

  return values;
}

