// A minimal re-implementation of Python's bidict (bidirectional mapping)
// behavior needed by test2.mjs: forward and reverse lookups stay consistent.

export class KeyError extends Error {
  constructor(key) {
    super(String(key));
    this.name = 'KeyError';
    this.key = key;
  }
}

export class Bidict {
  constructor(entries = {}) {
    // Plain objects used as forward/reverse stores.
    this._fwd = Object.create(null);
    this._rev = Object.create(null);
    for (const [key, value] of Object.entries(entries)) {
      this.put(key, value);
    }
  }

  /**
   * Set a key -> value pair, keeping the reverse mapping consistent.
   * Setting a value that already exists under another key overwrites
   * that other key, matching bidict semantics.
   */
  put(key, value) {
    if (Object.prototype.hasOwnProperty.call(this._fwd, key)) {
      delete this._rev[this._fwd[key]];
    }
    if (Object.prototype.hasOwnProperty.call(this._rev, value)) {
      delete this._fwd[this._rev[value]];
    }
    this._fwd[key] = value;
    this._rev[value] = key;
  }

  /**
   * Look up the value for a key. Throws KeyError if absent,
   * like Python's `b[key]` on a missing key.
   */
  get(key) {
    if (!Object.prototype.hasOwnProperty.call(this._fwd, key)) {
      throw new KeyError(key);
    }
    return this._fwd[key];
  }

  /** Look up the key for a value (the inverse direction). */
  inverse(value) {
    if (!Object.prototype.hasOwnProperty.call(this._rev, value)) {
      throw new KeyError(value);
    }
    return this._rev[value];
  }
}

