// Entry point mirroring /workspace/dataset/bidict/test2.py.
// Usage: node test2.mjs --key <key> --val <val>

import { parseArgs } from './argparse.mjs';
import { Bidict, KeyError } from './bidict.mjs';

const args = parseArgs(process.argv.slice(2));

// 创建双向字典并访问值
const b = new Bidict({ a: 1, b: 2 });

let result;
try {
  result = b.get(args.key);
} catch (err) {
  if (err instanceof KeyError) {
    // Python exits with an unhandled KeyError (return code 1).
    console.error(`KeyError: '${err.key}'`);
    process.exit(1);
  }
  throw err;
}

console.log(result);

